#!/bin/zsh
# Runs the Argent e2e suite on one booted simulator or emulator with the Release harness installed,
# then writes e2e/results/argent/review.html.
#   e2e/argent/run.sh <simulator UDID or adb serial> [--spam] [name filter]
# By default the visual suite (apps/harness/.argent/e2e, generated by build.py); --spam runs the spam
# matrix instead (.argent/e2e/spam, generated by e2e/scenarios/spam-matrix.py --emit).
U=$1; shift; SPAM=0
[[ $1 == --spam ]] && { SPAM=1; shift; }
FILTER=${1:-}; H=${0:a:h:h:h}
[[ -z $U ]] && { echo "usage: run.sh <device> [--spam] [filter]" >&2; exit 2; }
cd $H || exit 1
mkdir -p e2e/results/argent
echo $U > .argent/device
DIR=.argent/e2e
if (( SPAM )); then
  # The spam tests are generated, not kept: write them from the matrix as it is now.
  DIR=.argent/e2e/spam
  PLATFORM=android; [[ $U =~ '^[0-9A-F]{8}-' ]] && PLATFORM=ios
  # An emulator draws and records at ~15 fps: too few frames to judge, so it checks end states only.
  TRACK=(); [[ $U == emulator-* ]] && TRACK=(--no-track)
  python3 -I e2e/scenarios/spam-matrix.py --emit --platform $PLATFORM $TRACK || exit 1
fi
FAILED=()
for test in $DIR/*.yaml(N); do
  name=${test:t:r}
  [[ -n $FILTER && $name != *$FILTER* ]] && continue
  if argent e2e run $test --device $U > e2e/results/argent-$name.log 2>&1; then
    if (( SPAM )); then
      printf "%-58s pass\n" $name
    else
      printf "%-28s pass %s\n" $name "$(grep -o 'blank [0-9]*, flicker [0-9]*, jump [0-9]*' e2e/results/argent-$name.log | tail -1)"
    fi
  else
    FAILED+=$name
    printf "%-28s FAIL %s\n" $name "$(grep -m1 -E '✗|errored' e2e/results/argent-$name.log | cut -c1-160)"
  fi
done
python3 -I e2e/visual/review.py e2e/results/argent
echo "${#FAILED} failed${FAILED:+: $FAILED}"
(( ${#FAILED} == 0 ))
